export const blankProgress=()=>({version:3,answers:{},visual:{},notes:{},bookmarks:{},sessions:{},updated:0});
export function mergeProgress(a,b){const result=blankProgress();for(const key of ['answers','visual','notes','bookmarks','sessions']){for(const source of [a,b]){if(!source||typeof source[key]!=='object'||!source[key])continue;for(const [id,value]of Object.entries(source[key])){if(!value||typeof value!=='object'||!Number.isFinite(value.at)||['__proto__','constructor','prototype'].includes(id))continue;if(!result[key][id]||value.at>=result[key][id].at)result[key][id]=value}}}result.updated=Math.max(Number(a?.updated)||0,Number(b?.updated)||0);return result}
export function validateBackup(data){if(data?.version!==3||!data.answers||!data.visual||!data.bookmarks)throw Error('backup');return mergeProgress(blankProgress(),data)}
export function progressStats(data){const a=Object.values(data.answers);return {answered:a.length,correct:a.filter(x=>x.correct).length,weak:a.filter(x=>!x.correct).length+Object.values(data.visual).filter(x=>x.needsReview).length}}
